# Looking at this pattern, it seems like the 4s form possible line segments
# Let me check if they align in any pattern

locations = [(1, 1), (1, 3), (1, 5), (6, 2), (6, 4), (8, 4), (8, 6), (8, 8), (8, 10), (8, 12)]

# Check for diagonal alignments
# For two points (r1, c1) and (r2, c2), they're on a diagonal if |r1-r2| == |c1-c2|
diagonals = []
for i in range(len(locations)):
    for j in range(i+1, len(locations)):
        r1, c1 = locations[i]
        r2, c2 = locations[j]
        if abs(r1 - r2) == abs(c1 - c2):
            # Diagonal direction
            if r1 < r2:
                diag = f"\\: ({r1},{c1}) to ({r2},{c2})"
            else:
                diag = f"/: ({r1},{c1}) to ({r2},{c2})"
            diagonals.append((r1, c1, r2, c2, diag))

print(f"Found {len(diagonals)} diagonal pairs:")
for d in diagonals[:10]:
    print(d)

# Debug: check what creates (7,4)
locations = [(1, 1), (1, 3), (1, 5), (6, 2), (6, 4), (8, 4), (8, 6), (8, 8), (8, 10), (8, 12)]

def same_color(p1, p2):
    r1, c1 = p1
    r2, c2 = p2
    return (r1 + c1) % 2 == (r2 + c2) % 2

# Check which pairs connect
found_74 = []
for i, (r1, c1) in enumerate(locations):
    for j in range(i+1, len(locations)):
        (r2, c2) = locations[j]
        dr = r2 - r1
        dc = c2 - c1

        if same_color((r1, c1), (r2, c2)):
            if dr == 0 and abs(dc) >= 2:  # horizontal
                for k in range(1, abs(dc)):
                    found_74.append(('', f'{(r1,c1)}->({r2,c2)}'))
            elif dc == 0 and abs(dr) >= 2:  # vertical
                for k in range(1, abs(dr)):
                    if (7,4) == (r1 + k * (1 if dr > 0 else -1), c1):
                        found_74.append(('V', f'{(r1,c1)}->({r2,c2)}'))
            elif abs(dr) == abs(dc) and abs(dr) >= 2:  # diagonal
                for k in range(1, abs(dr)):
                    if (7,4) == (r1 + k*dr, c1 + k*dc):
                        found_74.append(('D', f'{(r1,c1)}->({r2,c2)}'))

print(f"What creates (7,4)? {found_74}")

