# The problem: I was filling ALL intermediate cells between any two 4s on a line
# But I should only fill cells between ADJACENT (consecutive) 4s on each line

# Group 4s by line
locations = [(1,1), (1,3), (1,5), (6,2), (6,4), (8,4), (8,6), (8,8), (8,10), (8,12)]

# Find lines (H, V, D) and sort 4s along each line
def get_line_groups():
    lines = {'horizontal': [], 'vertical': [], 'diagonal': []}

    for i in range(len(locations)):
        for j in range(i+1, len(locations)):
            p1, p2 = locations[i], locations[j]
            dr, dc = p2[0]-p1[0], p2[1]-p1[1]

            if dr == 0:
                # Horizontal
                cols = sorted([p1[1], p2[1]])
                lines['horizontal'].append(sorted([p1, p2]))
            elif dc == 0:
                # Vertical
                rows = sorted([p1[0], p2[0]])
                lines['vertical'].append(sorted([p1, p2]))
            elif abs(dr) == abs(dc):
                # Diagonal
                lines['diagonal'].append(sorted([p1, p2]))

    # Sort 4s along each horizontal line by column
    for hline in lines['horizontal']:
        hline.sort(key=lambda p: p[1])

    # Sort 4s along each vertical line by row
    for vline in lines['vertical']:
        vline.sort(key=lambda p: p[0])

    # Sort 4s along each diagonal by diagonal direction
    for dline in lines['diagonal']:
        if dline[0][0] < dline[1][0]:
            dline.sort(key=lambda p: p[0])  # down-right or down-left
        else:
            dline.sort(key=lambda p: p[0])

    return lines

lines = get_line_groups()
print("Horizontal lines (with sorted 4 positions):")
for line in lines['horizontal']:
    print(f"  {line}")

print("\nVertical lines:")
for line in lines['vertical']:
    print(f"  {line}")

print("\nDiagonal lines:")
for line in lines['diagonal']:
    print(f"  {line}")

